contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, address target) public payable {
        require(address(this).balance >= amount, "insufficient test balance");

        // Fund the contract so that a non-owner call that somehow succeeded would move Ether.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "funding failed");

        uint balBefore = address(c).balance;

        // Non-owner attempts to withdraw all: must revert and not move Ether.
        bool withdrawAllReverted;
        try c.withdrawAll() {
            withdrawAllReverted = false;
        } catch {
            withdrawAllReverted = true;
        }

        // Non-owner attempts to withdraw a specific amount: must revert and not move Ether.
        bool withdrawReverted;
        try c.withdraw(amount) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Non-owner attempts to send money out: must revert and not move Ether.
        bool sendReverted;
        try c.sendMoney(target, amount) {
            sendReverted = false;
        } catch {
            sendReverted = true;
        }

        assert(withdrawAllReverted && withdrawReverted && sendReverted && address(c).balance == balBefore);
    }

    receive() external payable {}
}

