        c = _c;
    }

    receive() external payable {}

    function run(address attacker, uint value) public payable {
        require(attacker != address(this), "attacker must not be test contract");
        require(attacker != c.owner(), "attacker must not be owner");

        bool revertedWithdrawAll;
        bool revertedWithdraw;
        bool revertedSendMoney;

        (bool success, bytes memory data) = address(c).call(abi.encodeWithSignature("withdrawAll()"));
        revertedWithdrawAll = !success;

        (success, data) = address(c).call(abi.encodeWithSignature("withdraw(uint256)", value));
        revertedWithdraw = !success;

        (success, data) = address(c).call(abi.encodeWithSignature("sendMoney(address,uint256)", attacker, value));
