contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address target, uint depositAmount, uint sendAmount) public payable {
        require(target != address(0));
        require(address(this).balance >= depositAmount);

        (bool okDeposit, ) = address(c).call{value: depositAmount}("");
        require(okDeposit, "deposit failed");

        uint beforeDeposits = c.depositsCount();
        uint beforeBalance = target.balance;
        uint beforeCBalance = address(c).balance;

        bool reverted;
        try c.sendMoney(target, sendAmount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (reverted) {
            assert(c.depositsCount() == beforeDeposits);
            assert(address(c).balance == beforeCBalance);
            assert(target.balance == beforeBalance);
        } else {
            assert(address(c).balance == beforeCBalance - sendAmount - depositAmount);
        }
    }

    receive() external payable {}
}

