contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint amount, address attacker) public payable {
        require(attacker != address(this), "attacker must not be this contract");
        require(attacker != address(c), "attacker must not be C");
        require(attacker != address(0), "attacker must not be zero address");

        // Setup: deposit some Ether into c so balance is non-zero
        if (amount > 0) {
            require(address(this).balance >= amount, "insufficient balance");
            (bool ok1, ) = address(c).call{value: amount}("");
            require(ok1, "deposit failed");
        }

        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // Non-owner call to withdrawAll must revert
        bool reverted;
        // We need to call from a non-owner address. Since the test contract is the owner,
        // we use a low-level call from the attacker address. But we cannot change msg.sender
        // for a direct call. Instead, we simulate the non-owner by calling withdrawAll through
        // a separate call where msg.sender is the attacker. However, the test contract cannot
        // impersonate another address. The only way is to have the attacker be a contract that
        // calls c.withdrawAll(), but we cannot deploy new contracts. 
        // Alternative: Since the test contract is the owner, any call from it would succeed.
        // The property "non-owner withdrawAll reverts" cannot be tested directly from this contract.
        // So we choose a different observable rule: withdrawAll always empties c's balance.
        // But that's already accepted. We need a different rule.

        // Let's focus on: depositsCount increments by exactly 1 for each successful receive.
        // But we need a rule that is general and not already accepted.
        // Accepted rules cover sendMoney and withdraw. We can test that after withdrawAll, 
        // the owner can still receive Ether and depositsCount increments.

        // Let's choose: For the owner, calling withdrawAll with zero balance does not revert and 
        // leaves depositsCount unchanged.
        // But that might be trivial. 

        // Better: The depositsCount is incremented only by receive() and never by withdraw or sendMoney.
        // We can test: after any sequence of owner operations (withdrawAll, withdraw, sendMoney),
        // depositsCount remains unchanged.
        // However, sendMoney can cause a receive on the target if it's a contract, but that's not c.
        // So we can set up: owner calls sendMoney to an address that is not c, then check depositsCount.
        // But we need to call from owner, which is the test contract.

        // Let's do: owner calls withdrawAll, then depositsCount should be unchanged.
        // But that's similar to accepted rule "withdrawAll never changes depositsCount".

        // We need a new rule. Consider: The contract's receive() increments depositsCount by exactly 1 
        // for each call, and the check `(depositsCount + 1) >= depositsCount` is always true.
        // So depositsCount increases by 1 on each successful receive.
        // We can test: sending Ether to c via a plain call increases depositsCount by exactly 1.
        // But that's basically the definition.

        // Maybe: withdrawAll transfers the entire balance to the owner, and the owner's balance increases by 
        // the amount withdrawn. But we are the owner, so we can check address(this).balance.
        // However, the test contract's balance also changes due to gas. We can measure before and after.
        // But gas makes it tricky.

        // Let's go with: For the owner, a successful withdraw(amount) where amount <= balance reduces 
        // the contract's balance by exactly amount and does not change depositsCount.
        // But that's already accepted ("when the owner withdraws a requested amount not exceeding C's balance, 
        // C's Ether balance decreases by exactly that amount").

        // New rule: withdrawAll always transfers the entire balance to the owner, so after withdrawAll, 
        // the owner's balance increases by exactly the contract's previous balance (ignoring gas).
        // But gas makes it not exact. We can use a different check: after withdrawAll, 
        // address(c).balance == 0.
        // But that's accepted.

        // Let's think of a rule about sendMoney: if sendMoney fails (target reverts), the whole transaction reverts.
        // That's accepted.

        // What about: depositsCount is never decremented, it only increases.
        // We can test: after any number of deposits, depositsCount >= initial depositsCount.
        // But that's trivial.

        // Perhaps: The contract's receive() function's require check is always true, so it never reverts 
        // due to overflow. So sending Ether to c always succeeds and increments depositsCount.
        // We can test: a direct call to receive() with value increments depositsCount by 1 and increases 
        // c's balance by the sent amount.
        // That's a good rule: For any amount, sending Ether to c increases c's balance by exactly amount 
        // and increments depositsCount by exactly 1.
        // We can set up: amount is parameter, we send amount to c, then check balance and depositsCount.
        // This is a general rule not in accepted list.

        // However, the accepted rules don't cover this. So let's do that.
        // But note: we must not read msg.value. We take amount as parameter and send it.

        // Setup: ensure we have enough balance. The test contract may already have some balance from 
        // constructor? We can require address(this).balance >= amount.
        // But the test contract is deployed with some balance? The checker might send Ether to it? 
        // We can make the function payable and require address(this).balance >= amount.
        // However, if we don't have enough, the test would revert. The checker may provide balance.
        // To be safe, we can require that the test contract has at least amount, but if not, the test fails.
        // The problem says: "If Ether is needed, the function may be payable and may call c.f{value: amount}(...), 
        // with amount from a parameter, plus require(address(this).balance >= amount)."
        // So we do that.

        require(address(this).balance >= amount, "insufficient balance");

        uint balanceBefore = address(c).balance;
        uint depositsBefore = c.depositsCount();

        // Send Ether to c via a call to its receive function
        (bool success, ) = address(c).call{value: amount}("");
        require(success, "deposit failed");

        uint balanceAfter = address(c).balance;
        uint depositsAfter = c.depositsCount();

        assert(balanceAfter == balanceBefore + amount && depositsAfter == depositsBefore + 1);
    }

    receive() external payable {}
}

